#!/usr/bin/env python
# -*- coding: utf-8 -*-
"""Re-fix the 4 new AD articles whose body wasn't replaced (regex bug).

Strategy:
  1. Find <article class="max-w-3xl..."> open tag with regex
  2. Walk forward to matching </article>
  3. Replace inner content
"""
import re, sys, io, os
sys.stdout = io.TextIOWrapper(sys.stdout.buffer, encoding='utf-8')

ROOT = r'C:\Users\User\Desktop\翊嘉\程式\個人網頁\DermNotes'

def replace_article_body(html, new_article_inner):
    m = re.search(r'<article\s+class="max-w-3xl[^"]*"[^>]*>', html)
    if not m:
        return None
    open_tag_start = m.start()
    open_tag_end = m.end()
    depth = 1
    i = open_tag_end
    while i < len(html) and depth > 0:
        no = html.find('<article', i)
        nc = html.find('</article>', i)
        if nc < 0: break
        if no >= 0 and no < nc:
            depth += 1; i = no + 8
        else:
            depth -= 1; i = nc + 10
    end = i
    return html[:open_tag_start] + new_article_inner + html[end:]


